import type { AvatarProps, AvatarImageProps, AvatarFallbackProps } from "./avatar.types";

import React, { forwardRef, useState, useCallback } from "react";
import { clsx } from "clsx";
import { useTheme } from "@theme";
import { Image } from "@components/image";
import { User as UserIcon } from "@exp-textura/icons";

import { AvatarClasses, StyledAvatar } from "./avatar.styles";
import { AvatarContext, useAvatar } from "./hooks/use-avatar";

const AvatarRoot = forwardRef<HTMLDivElement, AvatarProps>(
  (
    {
      size = "lg",
      className,
      variant = "default",
      ring,
      children,
      name,
      style,
      isOverflow = false,
      ...props
    },
    ref,
  ) => {
    const theme = useTheme();
    const [imageStatus, setImageStatus] = useState<"loading" | "success" | "error">("loading");

    const rootClasses = clsx(
      AvatarClasses.root,
      {
        [AvatarClasses.ring]: !!ring,
        [AvatarClasses[size]]: true,
      },
      className,
    );

    const contextValue = {
      imageStatus,
      setImageStatus,
      name,
      size,
      isOverflow,
    };

    return (
      <AvatarContext.Provider value={contextValue}>
        <StyledAvatar
          ref={ref}
          className={rootClasses}
          currentTheme={theme}
          style={{
            width: size,
            height: size,
            outlineColor: ring,
            ...style,
          }}
          variant={variant}
          {...props}
        >
          {children}
        </StyledAvatar>
      </AvatarContext.Provider>
    );
  },
);
AvatarRoot.displayName = "Avatar";

const AvatarImage: React.FC<AvatarImageProps> = ({ alt, objectFit, src, ...props }) => {
  const { setImageStatus, name: contextName } = useAvatar();

  const handleLoad = useCallback(() => {
    setImageStatus("success");
  }, [setImageStatus]);

  const handleError = useCallback(() => {
    setImageStatus("error");
  }, [setImageStatus]);

  return (
    <Image
      alt={alt ?? contextName ?? ""}
      className={AvatarClasses.image}
      objectFit={objectFit}
      src={src}
      onLoad={handleLoad}
      onSrcError={handleError}
      {...props}
    />
  );
};
AvatarImage.displayName = "Avatar.Image";

const AvatarFallback: React.FC<AvatarFallbackProps> = ({ children, name, ...props }) => {
  const { imageStatus, name: contextName, size, isOverflow } = useAvatar();
  const displayName = name || contextName;

  if (imageStatus === "success") return null;

  // Convert name into capitalized initials, prioritizing children, then local name, then context name
  const fallbackText = displayName
    ? displayName
        ?.split(" ")
        .map((word) => word[0])
        .join("")
        .toUpperCase()
    : undefined;

  let finalContent = children ?? fallbackText ?? <UserIcon />;
  const ariaLabel =
    props["aria-label"] ??
    displayName ??
    (typeof finalContent === "string"
      ? finalContent
      : React.isValidElement(finalContent)
        ? undefined
        : String(finalContent).replace(/,/g, ""));
  const isMonogram = !!fallbackText && !children;

  const fallbackClasses = clsx(AvatarClasses.monogram, {
    [AvatarClasses.icon]: !isMonogram && React.isValidElement(finalContent),
    [AvatarClasses.overflow]: (!isMonogram && typeof finalContent === "string") || isOverflow,
  });

  if (typeof finalContent === "string" && size.includes("xsm")) {
    finalContent = finalContent[0];
  }

  return (
    <div aria-label={ariaLabel} className={fallbackClasses} role="img" {...props}>
      {finalContent}
    </div>
  );
};
AvatarFallback.displayName = "Avatar.Fallback";

const Avatar = Object.assign(AvatarRoot, {
  Image: AvatarImage,
  Fallback: AvatarFallback,
});

export default Avatar;
